-- AutoLux Phase 3: public vehicle catalogue and fleet foundation
CREATE TABLE IF NOT EXISTS vehicles (
  id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  stock_code text NOT NULL UNIQUE,
  slug text NOT NULL UNIQUE,
  make text NOT NULL,
  model text NOT NULL,
  model_year smallint NOT NULL CHECK (model_year BETWEEN 1990 AND 2100),
  category text NOT NULL,
  listing_type text NOT NULL DEFAULT 'both' CHECK (listing_type IN ('rental','sale','both')),
  description text NOT NULL DEFAULT '',
  daily_rental_price_usd numeric(10,2) CHECK (daily_rental_price_usd >= 0),
  weekly_rental_price_usd numeric(10,2) CHECK (weekly_rental_price_usd >= 0),
  monthly_rental_price_usd numeric(10,2) CHECK (monthly_rental_price_usd >= 0),
  sale_price_usd numeric(12,2) CHECK (sale_price_usd >= 0),
  sale_price_basis text NOT NULL DEFAULT 'admin_set' CHECK (sale_price_basis IN ('model_median','segment_estimate','admin_set')),
  price_reference_date date,
  price_reference_url text,
  daily_rental_price_basis text NOT NULL DEFAULT 'admin_set',
  rental_price_reference_url text,
  transmission text NOT NULL DEFAULT 'Automatic',
  fuel_type text NOT NULL DEFAULT 'Gasoline',
  seats smallint NOT NULL DEFAULT 5 CHECK (seats BETWEEN 1 AND 20),
  doors smallint NOT NULL DEFAULT 4 CHECK (doors BETWEEN 2 AND 6),
  mileage_limit_per_day integer CHECK (mileage_limit_per_day >= 0),
  branch_id uuid REFERENCES branches(id) ON DELETE SET NULL,
  registration_number text,
  status text NOT NULL DEFAULT 'available' CHECK (status IN ('available','reserved','rented','under_maintenance','damaged','inactive')),
  image_url text,
  image_search_query text,
  image_source_url text,
  image_license text,
  image_credit text,
  is_demo boolean NOT NULL DEFAULT false,
  published boolean NOT NULL DEFAULT false,
  archived_at timestamptz,
  created_by uuid REFERENCES users(id) ON DELETE SET NULL,
  updated_by uuid REFERENCES users(id) ON DELETE SET NULL,
  created_at timestamptz NOT NULL DEFAULT now(),
  updated_at timestamptz NOT NULL DEFAULT now()
);
CREATE INDEX IF NOT EXISTS vehicles_public_catalog_idx ON vehicles(published, status, category, make) WHERE archived_at IS NULL;
CREATE INDEX IF NOT EXISTS vehicles_branch_status_idx ON vehicles(branch_id, status) WHERE archived_at IS NULL;
CREATE INDEX IF NOT EXISTS vehicles_price_idx ON vehicles(daily_rental_price_usd, sale_price_usd) WHERE published = true AND archived_at IS NULL;
CREATE INDEX IF NOT EXISTS vehicles_search_idx ON vehicles USING gin (to_tsvector('english', make || ' ' || model || ' ' || category || ' ' || description));

CREATE TABLE IF NOT EXISTS vehicle_images (
  id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  vehicle_id uuid NOT NULL REFERENCES vehicles(id) ON DELETE CASCADE,
  image_url text NOT NULL,
  source_page_url text NOT NULL,
  license_name text NOT NULL,
  creator_credit text,
  alt_text text NOT NULL,
  sort_order smallint NOT NULL DEFAULT 0,
  created_at timestamptz NOT NULL DEFAULT now()
);
CREATE INDEX IF NOT EXISTS vehicle_images_vehicle_idx ON vehicle_images(vehicle_id, sort_order);

CREATE TABLE IF NOT EXISTS vehicle_status_history (
  id bigserial PRIMARY KEY,
  vehicle_id uuid NOT NULL REFERENCES vehicles(id) ON DELETE CASCADE,
  previous_status text,
  new_status text NOT NULL,
  changed_by uuid REFERENCES users(id) ON DELETE SET NULL,
  note text,
  created_at timestamptz NOT NULL DEFAULT now()
);
CREATE INDEX IF NOT EXISTS vehicle_status_history_vehicle_idx ON vehicle_status_history(vehicle_id, created_at DESC);

